  var varsQueued = false;
  var flushVars = function () {
    if (!varsQueued) return;
    varsQueued = false;
    post({ vars: JSON.parse(JSON.stringify(player.variables())), state: player.debugState() });
  };
  var postVars = function () {
    if (varsQueued) return;
    varsQueued = true;
    requestAnimationFrame(flushVars);
    setTimeout(flushVars, 100);
  };
  player.on('variablechange', postVars);
  player.on('artboardchange', postVars);
  player.on('trace', function (t) { post({ trace: t }); });
  player.on('scripterror', function (e) { post({ scripterror: e }); });
  player.on('announce', function (a) { post({ announce: a }); });
  postVars();
  setInterval(function () { post({ state: player.debugState() }); }, 250);
